CREATE SCHEMA IF NOT EXISTS pilot;
CREATE TABLE pilot.principals(principal_id text PRIMARY KEY,account_id text NOT NULL,permission_epoch integer NOT NULL DEFAULT 1,consent_version text,disabled_at timestamptz);
CREATE TABLE pilot.identity_bindings(issuer text NOT NULL,subject text NOT NULL,principal_id text NOT NULL REFERENCES pilot.principals,PRIMARY KEY(issuer,subject));
CREATE TABLE pilot.workspaces(workspace_id text PRIMARY KEY,owner_id text NOT NULL REFERENCES pilot.principals,revision bigint NOT NULL DEFAULT 0);
CREATE TABLE pilot.members(workspace_id text REFERENCES pilot.workspaces,principal_id text REFERENCES pilot.principals,can_author boolean NOT NULL DEFAULT false,revoked_at timestamptz,PRIMARY KEY(workspace_id,principal_id));
-- Canonical event payloads/IDs, shared by both interfaces; this is a fresh platform store.
CREATE TABLE pilot.events(event_id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES pilot.workspaces,sequence bigint NOT NULL,type text NOT NULL,payload jsonb NOT NULL,actor text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),operation_id text NOT NULL,UNIQUE(workspace_id,sequence));
CREATE TABLE pilot.drafts(draft_id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES pilot.workspaces,actor_id text NOT NULL REFERENCES pilot.principals,revision integer NOT NULL CHECK(revision>0),payload jsonb NOT NULL,expires_at timestamptz NOT NULL,state text NOT NULL DEFAULT 'active' CHECK(state IN('active','applied','discarded')));
CREATE TABLE pilot.operations(operation_id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES pilot.workspaces,actor_id text NOT NULL REFERENCES pilot.principals,request_hash text NOT NULL,receipt jsonb NOT NULL);
CREATE TABLE pilot.sources(source_id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES pilot.workspaces,generation bigint NOT NULL DEFAULT 1,withdrawn_at timestamptz,erase_by timestamptz);
CREATE TABLE pilot.objects(object_id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES pilot.workspaces,source_id text NOT NULL REFERENCES pilot.sources,source_generation bigint NOT NULL,object_key text UNIQUE NOT NULL,storage_generation text,sha256 text NOT NULL,state text NOT NULL CHECK(state IN('pending','live','erase','erased')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),erased_at timestamptz);
CREATE TABLE pilot.jobs(job_id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES pilot.workspaces,source_id text REFERENCES pilot.sources,source_generation bigint,kind text NOT NULL CHECK(kind IN('index','cleanup')),state text NOT NULL DEFAULT 'due' CHECK(state IN('due','leased','done','cancelled')),due_at timestamptz NOT NULL DEFAULT clock_timestamp(),lease_until timestamptz,lease_owner text,fence bigint NOT NULL DEFAULT 0,attempts integer NOT NULL DEFAULT 0,operation_id text NOT NULL UNIQUE);
-- Paid retries must reconcile the ORIGINAL attempt and reservation. Mechanics never dispatch providers.
CREATE TABLE pilot.provider_attempts(attempt_id text PRIMARY KEY,job_id text NOT NULL REFERENCES pilot.jobs,reservation_id text NOT NULL UNIQUE,provider_request_id text,state text NOT NULL CHECK(state IN('reserved','dispatched','uncertain','settled')),generation bigint NOT NULL,amount_micros bigint NOT NULL CHECK(amount_micros>=0));
CREATE TABLE pilot.job_effects(operation_id text PRIMARY KEY,job_id text NOT NULL REFERENCES pilot.jobs,fence bigint NOT NULL,completed_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE pilot.wakes(wake_id text PRIMARY KEY,started_at timestamptz NOT NULL DEFAULT clock_timestamp(),finished_at timestamptz,source_commit text NOT NULL,claimed integer NOT NULL DEFAULT 0,completed integer NOT NULL DEFAULT 0,error_code text);
